-- Standard 8-digit HSN codes for final products (seeded from Odoo), matched by product name.
CREATE TABLE public.hsn_codes (
  code text PRIMARY KEY CHECK (code ~ '^[0-9]{8}$'),
  description text NOT NULL DEFAULT '',
  keywords text[] NOT NULL DEFAULT '{}',
  examples text[] NOT NULL DEFAULT '{}',
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now()
);
GRANT SELECT, INSERT, UPDATE, DELETE ON public.hsn_codes TO authenticated;
GRANT ALL ON public.hsn_codes TO service_role;
ALTER TABLE public.hsn_codes ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Team reads HSN codes" ON public.hsn_codes FOR SELECT TO authenticated USING (public.is_admin_or_team(auth.uid()));
CREATE POLICY "Team edits HSN codes" ON public.hsn_codes FOR ALL TO authenticated
  USING (public.is_admin_or_team(auth.uid())) WITH CHECK (public.is_admin_or_team(auth.uid()));
CREATE TRIGGER hsn_codes_updated_at BEFORE UPDATE ON public.hsn_codes FOR EACH ROW EXECUTE FUNCTION public.update_updated_at_column();
ON CONFLICT (code) DO NOTHING;
